// The Omniscient Intelligence Engine Core
const stockRes = $('O1 — Fetch Total Inventory').item.json;
const salesRes = $('O2 — Fetch Recent Sales Velocity').item.json;

const stock = stockRes.data || [];
const sales = salesRes.data || [];

// 1. Find overstocked items (high quantity) and understocked
let overstocked = [];
let criticalLow = [];
for (const item of stock) {
  const attr = item.attributes || item;
  if (attr.quantity > 500) overstocked.push(attr);
  if (attr.quantity < 20) criticalLow.push(attr);
}

// 2. Sales Velocity (What's selling fast vs slow)
let dishVelocity = {};
for (const o of sales) {
  const attr = o.attributes || o;
  const items = attr.order_items?.data || attr.order_items || [];
  for (const i of items) {
    const iAttr = i.attributes || i;
    const label = iAttr.label || 'Unknown';
    dishVelocity[label] = (dishVelocity[label] || 0) + (iAttr.qty || 1);
  }
}

// Sort velocity
const velocityArray = Object.entries(dishVelocity).sort((a, b) => b[1] - a[1]);
const topSelling = velocityArray.slice(0, 3);
const slowSelling = velocityArray.slice(-3);

// Construct the Master Brain payload
return [{ json: {
  cross_correlation: {
    overstocked_ingredients: overstocked.map(i => `${i.name} (${i.quantity} ${i.unit})`),
    critical_shortages: criticalLow.map(i => `${i.name} (${i.quantity} ${i.unit})`),
    trending_dishes: topSelling.map(d => `${d[0]} (x${d[1]})`),
    slow_dishes: slowSelling.map(d => `${d[0]} (x${d[1]})`)
  }
}}];

