// The Orchestrator decides which specialist agents to wake up
const data = $('O3 — Cross-Correlate Data Vectors').item.json.cross_correlation;
const strategy = $('O5 — Parse Grand Strategy').item.json;

const triggers = [];

// 1. If we have overstock, trigger Growth Agent for a Promo
if (data.overstocked_ingredients && data.overstocked_ingredients.length > 0) {
  triggers.push({
    agent: 'W_GROWTH_AGENT',
    reason: 'OVERSTOCK_PROMO',
    payload: { items: data.overstocked_ingredients }
  });
}

// 2. If we have critical shortages, trigger Revenue Intelligence for impact analysis
if (data.critical_shortages && data.critical_shortages.length > 0) {
  triggers.push({
    agent: 'W_REVENUE_INTELLIGENCE',
    reason: 'SHORTAGE_ALERT',
    payload: { items: data.critical_shortages }
  });
}

// 3. If velocity is high, suggest Logistics surge (manual for now, but logged)
if (data.trending_dishes && data.trending_dishes.length > 5) {
   triggers.push({
    agent: 'W_LOGISTICS_PRO',
    reason: 'SURGE_ANTICIPATION',
    payload: { dishes: data.trending_dishes }
  });
}

return triggers.map(t => ({ json: t }));
